  { state, getters, mutations },
  {
    async init ({ state }) {
      $storex.ui.handleResize()
      window.addEventListener('resize', () => $storex.ui.handleResize())
      if (API.user?.theme) {
        state.theme = API.user.theme
      }
      state.coderProjectCodxPath = null
    },
    saveState({ state }) {
      if (!state.uiReady) {
        return
      }
      try {
        const data = { 
          ...state, 
          uiReady: false,
          openApps: {},
          viewEditor: null,
          projectLoadingState: {
            isLoading: false,
            projectName: '',
            currentStep: null,
            error: null
          }
        }
        localStorage.setItem('uiState', JSON.stringify(data))
      } catch (error) {
        console.error('Failed to save UI state:', error)
      }
    },
    async loadState({ state }) {
      try {
        const savedState = localStorage.getItem('uiState')
        if (savedState) {
          const parsedState = JSON.parse(savedState)
          Object.keys(parsedState)
            .forEach(k => state[k] = parsedState[k])
        }
      } catch (error) {
        console.error('Failed to parse saved UI state:', error)
      }

      const {
        activeProject: project_id,
        activeChat: chatId
      } = state

      if (project_id && project_id !== $storex.projects.activeProject?.project_id) {
        await $storex.projects.activeProjectChanged({ project_id })
      }
      if (chatId && $storex.projects.activeProject) {
        $storex.projects.setActiveChat({ id: chatId })
      }

      $storex.ui.handleResize()
    },
    handleResize({ state }) {
      const width = window.innerWidth
      const height = window.innerHeight
      const isMobile = width <= 1024
      const orientation = width > height ? 'landscape' : 'portrait'
      state.isMobile = isMobile
      state.orientation = orientation  
    },
    loadTask (_, task) {
      $storex.projects.setActiveChat(task)
    },
    async openFile({ state }, file) {
      if (state.isMobile) {
        state.openedFile = file
      } else {
        await API.coder.openFile(file)
      }
      state.showCoder = true
    },
    async openProjectFile({ state }, file) {
      const { project_path } = $storex.projects.activeProject
      if (!file.startsWith(project_path)) {
        if (!file.startsWith("/") && !project_path.endsWith("/")) {
          file = "/" + file
        }
        file = project_path + file
      }
      await API.coder.openFile(file)
      state.showCoder = true
    },
    setScreenResolution(_, resolution) {
      API.screen.setScreenResolution(resolution)
    },
    async readScreenResolutions ({ state }) {
      await API.screen.getScreenResolution()
      state.resolution = API.screen.display?.resolution
      state.resolutions = API.screen.display?.resolutions
    },
    copyTextToClipboard(_, text) {
      const textArea = document.createElement('textarea')
      textArea.value = text
      document.body.appendChild(textArea)
      textArea.focus()
      textArea.select()
      document.execCommand('copy')
      document.body.removeChild(textArea)
      $storex.ui.addNotification({ text: "Text copied" })
    },
    async readClipboardText(_, itemType = "text/plain") {
      const items = await navigator.clipboard.read()
      const getText = async item => {
        const blob = await item.getType(itemType)
        return await blob.text()
      }
      const allTexts = await Promise.all(
                        items.filter(i => i.types.includes(itemType))
                              .map(i => getText(i)))
      return allTexts.reduce((a, b) => a + b, "")
    },
    async shareScreen() {
      const stream = await navigator.mediaDevices.getDisplayMedia({
        preferCurrentTab: true,
      })
      const [track] = stream.getVideoTracks()
    },
    openNewWindowAppPanel(_, app) {
      const { origin } = window.location
      const url = `${origin}${app.path}`
      window.open(url, app.name)
    },

    openTeamChannel(_, { team, channel }) {
      $storex.ui.showApp({
        tabId: `team-channel-${channel.id}`,
        name: `# ${channel.name}`,
        component: 'team-channel',
        params: { team, channel }
      })
    },

    async openTeamDM(_, { team, member }) {
      const chatId = await $storex.teams.openDirectMessage({ teamId: team.id, member })
      $storex.ui.showApp({
        tabId: `team-dm-${team.id}-${member.id}`,
        name: `@ ${member.username}`,
        component: 'team-dm',
        params: { team, member, chatId }
      })
    },

    openTeamMediaLibrary(_, { team }) {
      $storex.ui.showApp({
        tabId: `team-media-${team.id}`,
        name: `🖼 ${team.name} Media`,
        component: 'team-media-library',
        params: { team }
      })
    },

    openVibeCoding() {
      $storex.ui.showApp({
        key: 'vibe-coding',
        name: 'Vibe Coding',
        component: 'vibe-coding',
        params: {}
      })
    },

    openProjects() {
      $storex.ui.showApp({
        tabId: 'projects',
        name: 'Projects',
        component: 'projects',
        params: {}
      })
    },

    openTeams() {
      $storex.ui.showApp({
        tabId: 'teams',
        name: 'Teams',
        component: 'teams',
        params: {}
      })
    },

    openWorkspaces() {
      $storex.ui.showApp({
        tabId: 'workspaces',
        name: 'Workspaces',
        component: 'workspaces',
        params: {}
      })
    },

    openTasks() {
      $storex.ui.setActiveTab('tasks')
    },

    openWiki() {
      $storex.ui.setActiveTab('wiki')
    },

    openMediaLibrary() {
      $storex.ui.showApp({
        tgabId: 'media-library',
        name: 'Media Library',
        compotabIdnent: 'media-library',
        params: {}
      })
    },

    openHome() {
      $storex.ui.setActiveTab('home')
    },

    openTutorial(_, tutorialId) {
      $storex.ui.showApp({
        tabId: `tutorial-${tutorialId}`,
        name: 'Knowledge',
        component: 'knowledge',
        params: { tutorial: tutorialId }
      })
    },

    setProjectLoading(_, isLoading) {
      $storex.ui.setProjectLoadingState({ isLoading })
    },

    updateProjectLoadingStep(_, { stepId, status, options = {} }) {
      window.dispatchEvent(new CustomEvent('project-loading-step', {
        detail: { stepId, status, options }
      }))
    },

    setProjectLoadingError(_, error) {
      $storex.ui.setProjectLoadingState({ error })
    },

    checkAndActivateDesktopPanel(_, { component, params = {} }) {
      const desktopApi = $storex.views._desktopApi
      if (!desktopApi) return false

      try {
        const panels = desktopApi.panels || []

        const existingPanel = panels.find(panel => {
          if (panel.component !== component) return false
          const panelParams = panel.params?.params || panel.params || {}
          return JSON.stringify(panelParams) === JSON.stringify(params)
        })

        if (existingPanel) {
          desktopApi.setActivePanel(existingPanel)
          return true
        }
      } catch (error) {
        console.error('Error checking desktop panels:', error)
      }

      return false
    },
  },
)
```

| File | Changes | Description |
|------|---------|-------------|
| `src/store/ui.js` | Added `checkAndActivateDesktopPanel` action | New action that checks if an app is already open in the Desktop API and activates the existing panel instead of creating a duplicate |

## Key Changes

### New Action: `checkAndActivateDesktopPanel`
- **Location**: `src/store/ui.js` - actions
- **Purpose**: Checks if an app with matching component and params already exists in the Desktop view
- **Returns**: `true` if panel was found and activated, `false` otherwise
- **Logic**:
  1. Gets the Desktop API from the views store
  2. Searches existing panels for matching component and params
  3. If found, activates that panel
  4. Returns success status for caller decision-making

## Usage

Components or actions can now call this before opening an app:

```js
// Example usage
const alreadyOpen = await $storex.ui.checkAndActivateDesktopPanel({
  component: 'chat',
  params: { chat: { id: 'chat-123' } }
})

if (!alreadyOpen) {
  // Only open new app if not already open
  $storex.ui.showApp({...})
}
```

This prevents duplicate tabs in the Desktop view and improves user experience by focusing existing instances.

